import{_ as t,o as a,c as o,a6 as s}from"./chunks/framework.DIp0zHSV.js";const u=JSON.parse('{"title":"HA Services: Implementation Notes","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/internals/ha-services.md","filePath":"architecture/internals/ha-services.md","lastUpdated":1791165399000}'),r={name:"architecture/internals/ha-services.md"};function n(c,e,d,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ha-services-implementation-notes" tabindex="-1">HA Services: Implementation Notes <a class="header-anchor" href="#ha-services-implementation-notes" aria-label="Permalink to &quot;HA Services: Implementation Notes&quot;">​</a></h1><blockquote><p><strong>Architecture reference</strong>: internals of the <code>lcards.*</code> action registration and push channel. For usage, parameters, and automation examples see the <strong><a href="/dev/configuration/ha-actions.html">HA Actions user guide</a></strong>.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The LCARdS integration registers a set of HA <strong>actions</strong> (formerly called services) under the <code>lcards</code> domain. Services are registered in <code>async_setup_entry()</code> and removed cleanly on <code>async_unload_entry()</code>, so they appear and disappear with the integration lifecycle.</p><p><strong>Source files:</strong></p><ul><li><code>custom_components/lcards/services.py</code>: handler implementations, voluptuous schemas</li><li><code>custom_components/lcards/services.yaml</code>: HA UI metadata (selector types, field labels)</li></ul><p>→ For full service descriptions, parameter tables, YAML examples, and automation recipes see the <strong><a href="/dev/configuration/ha-actions.html">HA Actions user guide</a></strong>.</p><hr><h2 id="service-groups-implementation-summary" tabindex="-1">Service Groups (Implementation Summary) <a class="header-anchor" href="#service-groups-implementation-summary" aria-label="Permalink to &quot;Service Groups (Implementation Summary)&quot;">​</a></h2><p>16 services total, registered from <code>_ALL_SERVICES</code> in <code>services.py</code>:</p><table tabindex="0"><thead><tr><th>Group</th><th>Services</th><th>Implementation pattern</th></tr></thead><tbody><tr><td><strong>Alert mode</strong></td><td><code>set_alert_mode</code>, <code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>, <code>clear_alert</code></td><td>Thin wrappers: delegate to <code>input_select.select_option</code> on <code>input_select.lcards_alert_mode</code>, <strong>unless</strong> a targeting field is given, in which case they fire a targeted <code>set_alert_mode</code> push event instead and leave the shared helper untouched. Idempotent. Schema: <code>voluptuous</code>.</td></tr><tr><td><strong>Frontend control</strong></td><td><code>reload</code>, <code>set_log_level</code></td><td>Always fire <code>lcards_event</code> on the HA bus via the push channel (see below), never conditional on targeting. <code>set_log_level</code> also updates the Python <code>logging</code> hierarchy.</td></tr><tr><td><strong>Screen effects &amp; sound</strong></td><td><code>trigger_effect</code>, <code>clear_effect</code>, <code>play_sound</code></td><td>Always fire via the push channel. <code>trigger_effect</code> sets per-slot (<code>backdrop</code>/<code>color</code>/<code>canvas</code>) effect layers with an optional auto-clear <code>duration</code>; <code>clear_effect</code> clears one slot or all; <code>play_sound</code> plays a configured UI event sound or one exact asset.</td></tr><tr><td><strong>Portal overlay</strong></td><td><code>show_portal_card</code>, <code>clear_portal_card</code></td><td>Always fire via the push channel. Cards are mounted in <code>PortalOverlayManager</code> under slot <code>&#39;ha-service&#39;</code>, independent of <code>&#39;alert-overlay&#39;</code> and <code>&#39;connection-overlay&#39;</code>.</td></tr><tr><td><strong>Borg</strong></td><td><code>borg_assimilate</code>, <code>borg_deassimilate</code></td><td>Always fire via the push channel. When targeting is specified, the shared <code>input_select.lcards_alert_mode</code> is <strong>not</strong> written; palette changes are local to matched devices only.</td></tr></tbody></table><p>All 16 services accept the same four optional targeting fields (<code>target_device_ids</code>, <code>target_device_names</code>, <code>target_user_ids</code>, <code>target_user_names</code>) resolved server-side by <code>_async_resolve_targets()</code> and merged (explicit IDs + name lookups) before being attached to the outgoing event as <code>target_device_ids</code>/<code>target_user_ids</code>. Omitting all four is a broadcast. → Full field semantics: <a href="/dev/configuration/ha-actions.html">HA Actions user guide</a>.</p><hr><h2 id="push-channel-architecture" tabindex="-1">Push Channel Architecture <a class="header-anchor" href="#push-channel-architecture" aria-label="Permalink to &quot;Push Channel Architecture&quot;">​</a></h2><p>Nine services (<code>reload</code>, <code>set_log_level</code>, <code>trigger_effect</code>, <code>clear_effect</code>, <code>play_sound</code>, <code>show_portal_card</code>, <code>clear_portal_card</code>, <code>borg_assimilate</code>, <code>borg_deassimilate</code>) always route through a dedicated <strong>server-push channel</strong> instead of the WebSocket request/response pattern. The 7 alert-mode services route through the same channel only when a targeting field is supplied (otherwise they write <code>input_select.lcards_alert_mode</code> directly; see the service table above):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Python service handler (via _fire_targeted_event())</span></span>
<span class="line"><span>    → hass.bus.async_fire(&quot;lcards_event&quot;, { &quot;action&quot;: &quot;...&quot;, ...payload })</span></span>
<span class="line"><span>        → HA internal event bus</span></span>
<span class="line"><span>            → ws_subscribe._forward() (websocket_api.py, @callback)</span></span>
<span class="line"><span>                → connection.send_message(event_message(...))</span></span>
<span class="line"><span>                    → every browser tab subscribed via lcards/subscribe</span></span>
<span class="line"><span>                        → IntegrationService._handleLcardsEvent(data)</span></span>
<span class="line"><span>                            → dispatches on payload.action (see event payload table</span></span>
<span class="line"><span>                              in HA Integration Architecture)</span></span></code></pre></div><p>Browser tabs subscribe using the <code>lcards/subscribe</code> WS command (not the HA-native <code>subscribeEvents</code> API, which is restricted to admin users for custom event types). This means <strong>all users including non-admins</strong> receive push events.</p><p>Transport is always a <strong>broadcast</strong>: every subscribed tab receives every event. When an event carries <code>target_device_ids</code>/<code>target_user_ids</code> (i.e. a service call supplied targeting fields), each <code>IntegrationService._isEventTargetedAtMe()</code> self-filters client-side and silently drops events not addressed to it; there is no server-side targeted delivery to a single connection.</p><p>→ See <a href="./../subsystems/integration-service.html#push-channel">Integration Service: Push Channel</a> for the JS-side implementation details.</p><hr><h2 id="graceful-degradation" tabindex="-1">Graceful Degradation <a class="header-anchor" href="#graceful-degradation" aria-label="Permalink to &quot;Graceful Degradation&quot;">​</a></h2><h3 id="missing-input-select-lcards-alert-mode" tabindex="-1">Missing <code>input_select.lcards_alert_mode</code> <a class="header-anchor" href="#missing-input-select-lcards-alert-mode" aria-label="Permalink to &quot;Missing \`input_select.lcards_alert_mode\`&quot;">​</a></h3><p>If the <code>input_select.lcards_alert_mode</code> helper hasn&#39;t been created (e.g. a fresh install without running the LCARdS setup helper), alert services log a <code>WARNING</code> and exit cleanly; they do <strong>not</strong> raise an exception or crash HA:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WARNING (MainThread) [custom_components.lcards.services]</span></span>
<span class="line"><span>LCARdS: failed to set alert mode &#39;red_alert&#39; - is input_select.lcards_alert_mode defined? (...)</span></span></code></pre></div><h3 id="integration-not-loaded" tabindex="-1">Integration not loaded <a class="header-anchor" href="#integration-not-loaded" aria-label="Permalink to &quot;Integration not loaded&quot;">​</a></h3><p>If the integration entry is not active, the <code>lcards.*</code> services are not registered and will not appear in Developer Tools → Actions or in automations.</p><hr><h2 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h2><ul><li>Alert services are intentionally <strong>thin wrappers</strong>: they delegate to <code>input_select.select_option</code> rather than directly touching JS state, because <code>input_select.lcards_alert_mode</code> is the established source of truth that HelperManager already monitors.</li><li>Services are idempotent: calling <code>lcards.red_alert</code> when already in red alert is harmless.</li><li>Schema validation is enforced by <code>voluptuous</code> in <code>services.py</code>; invalid <code>mode</code> or <code>level</code> values are rejected by HA before the handler fires.</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/dev/configuration/ha-actions.html">HA Actions: User Guide</a>: service descriptions, parameters, YAML, and automation examples</li><li><a href="./../ha-integration.html">HA Integration Architecture</a>: boot sequence, unload, Python component files</li><li><a href="./../subsystems/integration-service.html">Integration Service</a>: JS-side probe and push channel subscription</li><li><a href="./../subsystems/helper-manager.html">Helper Manager</a>: how <code>input_select.lcards_alert_mode</code> changes are consumed by the JS side</li></ul>`,33)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
